def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]
    if n == 1:
        return 'C' if last_opp == 'C' else 'D'

    opp_c = 0
    my_c = 0
    dd_same = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        if m == 'C':
            my_c += 1
        if m == 'D' and o == 'D':
            dd_same += 1

    opp_d = n - opp_c
    my_d = n - my_c
    opp_rate = opp_c / n

    recent_n = 15 if n > 15 else n
    recent_opp_c = 0
    for i in range(n - recent_n, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
    recent_rate = recent_opp_c / recent_n

    d_streak = 0
    for i in reversed(range(n)):
        if history[i][1] == 'D':
            d_streak += 1
        else:
            break

    resp_c_after_d = 0
    resp_d_after_d = 0
    for i in range(1, n):
        prev_my = history[i - 1][0]
        opp_now = history[i][1]
        if prev_my == 'D':
            if opp_now == 'C':
                resp_c_after_d += 1
            else:
                resp_d_after_d += 1

    if opp_c == 0:
        return 'D'
    if n >= 6 and recent_rate <= 0.15:
        return 'D'
    if n >= 10 and recent_rate <= 0.3 and opp_rate <= 0.45:
        return 'D'
    if n >= 15 and opp_rate <= 0.25:
        return 'D'
    if d_streak >= 5 and recent_rate <= 0.5 and opp_rate <= 0.6:
        return 'D'

    generous = False

    if (
        resp_c_after_d >= 1 and
        resp_d_after_d == 0 and
        opp_c == n and
        recent_rate >= 0.9
    ):
        generous = True
    elif (
        resp_c_after_d >= 2 and
        resp_d_after_d <= 1 and
        recent_rate >= 0.7 and
        opp_rate >= 0.6
    ):
        generous = True
    elif (
        resp_c_after_d >= 3 and
        resp_d_after_d * 2 <= resp_c_after_d and
        recent_rate >= 0.6 and
        opp_rate >= 0.5
    ):
        generous = True
    elif (
        n >= 10 and
        resp_c_after_d >= 1 and
        resp_d_after_d == 1 and
        opp_c >= n - 2 and
        recent_rate >= 0.9 and
        dd_same == 0
    ):
        generous = True

    if generous:
        if last_opp == 'C':
            return 'D'
        if n >= 2 and history[-2][0] == 'D':
            if recent_rate >= 0.45 and d_streak <= 2:
                return 'C'
            return 'D'
        if recent_rate < 0.35 or d_streak >= 4:
            return 'D'
        return 'D'

    if last_opp == 'C':
        if last_my == 'D':
            return 'C'

        if n == 2 and opp_c == n and my_d == 0:
            return 'D'

        if (
            n == 9 and
            last_my == 'C' and
            my_d <= 1 and
            recent_rate >= 0.75 and
            opp_rate >= 0.55
        ):
            return 'D'

        return 'C'

    prev_my = history[-2][0]

    if recent_rate < 0.5 and opp_rate < 0.6:
        return 'D'

    if my_d > opp_d + 2 and recent_rate > 0.3:
        return 'C'

    if d_streak >= 2 and opp_c >= 2 and recent_rate >= 0.3:
        return 'C'

    if prev_my == 'D':
        if recent_rate >= 0.6 and d_streak <= 2:
            return 'C'
        return 'D'

    if d_streak >= 2 and recent_rate > 0.75:
        return 'C'

    return 'D'
